(function(){'use strict';function boot(){var app=document.getElementById('dior-patient-portal-app');if(!app||app.__diorSafeNavigationReady)return;app.__diorSafeNavigationReady=!0;var titles={overview:'Patient Overview',appointments:'Telehealth Appointments',docs_meds:'Medical Docs & Prescriptions',telemedicine:'Telemedicine',medical_record:'Medical Record',payments:'Billing & Payment Statements',insurance:'Insurance Claim',documents:'Documents & Reports',emergency:'Emergency Support',feedback:'Feedback & Support',notifications:'Notification Inbox',consultation:'Consultation Room',settings:'Settings'};function activate(tabId,updateHash){if(!tabId)return!1;var panel=document.getElementById('tab-'+tabId);if(!panel||!app.contains(panel))return!1;app.querySelectorAll('.dior-nav-btn[data-tab]').forEach(function(button){button.classList.toggle('active',button.getAttribute('data-tab')===tabId)});app.querySelectorAll('.dior-tab-panel').forEach(function(item){item.classList.toggle('active',item===panel)});var title=document.getElementById('dior-current-page-title');if(title&&titles[tabId])title.textContent=titles[tabId];if(updateHash!==!1&&window.history&&window.history.replaceState){window.history.replaceState(null,'','#tab='+encodeURIComponent(tabId))}
return!0}
window.diorSafeSwitchPatientTab=activate;app.addEventListener('click',function(event){var button=event.target.closest('.dior-nav-btn[data-tab]');if(!button||!app.contains(button))return;var tabId=button.getAttribute('data-tab');if(!tabId)return;event.preventDefault();event.stopPropagation();activate(tabId,!0);if(tabId==='appointments'&&typeof window.diorSwitchApptSubTab==='function'){window.diorSwitchApptSubTab('today')}
if(window.innerWidth<=1024&&typeof window.diorCloseMobileDrawer==='function'){window.diorCloseMobileDrawer()}},!0);var hash=window.location.hash||'';if(hash.indexOf('#tab=')===0){var requested=decodeURIComponent(hash.substring(5));if(!activate(requested,!1))activate('overview',!1)}else{var active=app.querySelector('.dior-nav-btn.active[data-tab]');activate(active?active.getAttribute('data-tab'):'overview',!1)}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',boot,{once:!0})}else{boot()}})()